const std = @import("std");
const mem = std.mem;
const math = std.math;
const Allocator = mem.Allocator;
const types = @import("types.zig");
const Error = types.Error;
const Fixed32_32 = types.Fixed32_32;

const Shape = struct {
    dims: []usize,
    strides: []usize,

    pub fn init(allocator: Allocator, shape: []const usize) !Shape {
        const n = shape.len;
        const dims = try allocator.alloc(usize, n);
        errdefer allocator.free(dims);
        const strides = try allocator.alloc(usize, n);
        errdefer allocator.free(strides);
        @memcpy(dims, shape);
        if (n > 0) {
            strides[n - 1] = 1;
            var i: usize = n - 1;
            while (i > 0) : (i -= 1) {
                const r = @mulWithOverflow(strides[i], dims[i]);
                if (r[1] != 0) return Error.Overflow;
                strides[i - 1] = r[0];
            }
        }
        return .{ .dims = dims, .strides = strides };
    }

    pub fn deinit(self: *Shape, allocator: Allocator) void {
        allocator.free(self.dims);
        allocator.free(self.strides);
    }

    pub fn copy(self: *const Shape, allocator: Allocator) !Shape {
        return .{ .dims = try allocator.dupe(usize, self.dims), .strides = try allocator.dupe(usize, self.strides) };
    }

    pub fn totalSize(self: *const Shape) Error!usize {
        var total: usize = 1;
        for (self.dims) |d| {
            const r = @mulWithOverflow(total, d);
            if (r[1] != 0) return Error.Overflow;
            total = r[0];
        }
        return total;
    }

    pub fn equals(self: *const Shape, other: *const Shape) bool {
        return mem.eql(usize, self.dims, other.dims);
    }

    pub fn broadcastCompatible(self: *const Shape, target: *const Shape) bool {
        if (target.dims.len < self.dims.len) return false;
        const offset = target.dims.len - self.dims.len;
        var i: usize = 0;
        while (i < self.dims.len) : (i += 1) {
            const self_dim = self.dims[i];
            const target_dim = target.dims[offset + i];
            if (self_dim != target_dim and self_dim != 1) {
                return false;
            }
        }
        return true;
    }

    pub fn isContiguous(self: *const Shape) bool {
        if (self.dims.len == 0) return true;
        var expected: usize = 1;
        var i: usize = self.dims.len;
        while (i > 0) : (i -= 1) {
            const idx = i - 1;
            if (self.strides[idx] != expected) return false;
            expected *= self.dims[idx];
        }
        return true;
    }
};

pub const Tensor = struct {
    data: []f32,
    shape: Shape,
    allocator: Allocator,
    refcount: *usize,
    cow: *bool,
    mutex: *std.Thread.Mutex,

    pub fn init(allocator: Allocator, shape: []const usize) !Tensor {
        var total_size: usize = 1;
        for (shape) |dim| {
            if (dim == 0) return Error.InvalidShape;
            const r = @mulWithOverflow(total_size, dim);
            if (r[1] != 0) return Error.Overflow;
            total_size = r[0];
        }
        const data = try allocator.alloc(f32, total_size);
        @memset(data, 0);
        const sh = try Shape.init(allocator, shape);
        const refcount = try allocator.create(usize);
        refcount.* = 1;
        const cow = try allocator.create(bool);
        cow.* = false;
        const mutex = try allocator.create(std.Thread.Mutex);
        mutex.* = .{};
        return .{ .data = data, .shape = sh, .allocator = allocator, .refcount = refcount, .cow = cow, .mutex = mutex };
    }

    pub fn retain(self: *Tensor) void {
        _ = @atomicRmw(usize, self.refcount, .Add, 1, .AcqRel);
    }

    pub fn release(self: *Tensor) void {
        const prev = @atomicRmw(usize, self.refcount, .Sub, 1, .AcqRel);
        if (prev == 1) {
            self.deallocate();
        }
    }

    fn deallocate(self: *Tensor) void {
        self.allocator.free(self.data);
        self.shape.deinit(self.allocator);
        self.allocator.destroy(self.refcount);
        self.allocator.destroy(self.cow);
        self.allocator.destroy(self.mutex);
    }

    pub fn deinit(self: *Tensor) void {
        const prev = @atomicRmw(usize, self.refcount, .Sub, 1, .AcqRel);
        if (prev == 1) {
            self.deallocate();
        }
    }

    pub fn copy(self: *const Tensor, allocator: Allocator) !Tensor {
        const new_t = try init(allocator, self.shape.dims);
        @memcpy(new_t.data, self.data);
        return new_t;
    }

    fn ensureWritable(self: *Tensor) !void {
        const original_mutex = self.mutex;
        original_mutex.lock();

        if (!self.cow.*) {
            original_mutex.unlock();
            return;
        }

        const new_data = self.allocator.alloc(f32, self.data.len) catch |err| {
            original_mutex.unlock();
            return err;
        };
        @memcpy(new_data, self.data);

        const new_refcount = self.allocator.create(usize) catch |err| {
            self.allocator.free(new_data);
            original_mutex.unlock();
            return err;
        };
        new_refcount.* = 1;

        const new_cow = self.allocator.create(bool) catch |err| {
            self.allocator.destroy(new_refcount);
            self.allocator.free(new_data);
            original_mutex.unlock();
            return err;
        };
        new_cow.* = false;

        const new_mutex = self.allocator.create(std.Thread.Mutex) catch |err| {
            self.allocator.destroy(new_cow);
            self.allocator.destroy(new_refcount);
            self.allocator.free(new_data);
            original_mutex.unlock();
            return err;
        };
        new_mutex.* = .{};

        const old_refcount = @atomicRmw(usize, self.refcount, .Sub, 1, .AcqRel);
        const was_last = (old_refcount == 1);
        const old_data = self.data;
        const old_refcount_ptr = self.refcount;
        const old_cow_ptr = self.cow;
        const old_mutex_ptr = self.mutex;

        self.data = new_data;
        self.refcount = new_refcount;
        self.cow = new_cow;
        self.mutex = new_mutex;

        original_mutex.unlock();

        if (was_last) {
            self.allocator.free(old_data);
            self.allocator.destroy(old_refcount_ptr);
            self.allocator.destroy(old_cow_ptr);
            self.allocator.destroy(old_mutex_ptr);
        }
    }

    fn markShared(self: *Tensor) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        self.cow.* = true;
    }

    pub fn newView(self: *Tensor, shape: Shape) !Tensor {
        const shape_size = try shape.totalSize();
        const self_size = try self.shape.totalSize();
        if (shape_size != self_size) return Error.InvalidShape;
        self.retain();
        self.markShared();
        return .{ .data = self.data, .shape = shape, .allocator = self.allocator, .refcount = self.refcount, .cow = self.cow, .mutex = self.mutex };
    }

    pub fn reshape(self: *Tensor, new_shape: []const usize) !void {
        if (new_shape.len == 0) return Error.InvalidShape;
        var total: usize = 1;
        for (new_shape) |dim| total *= dim;
        const self_size = try self.shape.totalSize();
        if (total != self_size) return Error.InvalidShape;
        const new_sh = try Shape.init(self.allocator, new_shape);
        self.shape.deinit(self.allocator);
        self.shape = new_sh;
    }

    pub fn view(self: *Tensor, new_shape: []const usize) !Tensor {
        if (new_shape.len == 0) return Error.InvalidShape;
        var total: usize = 1;
        for (new_shape) |dim| total *= dim;
        const self_size = try self.shape.totalSize();
        if (total != self_size) return Error.InvalidShape;
        const new_sh = try Shape.init(self.allocator, new_shape);
        self.retain();
        self.markShared();
        return .{ .data = self.data, .shape = new_sh, .allocator = self.allocator, .refcount = self.refcount, .cow = self.cow, .mutex = self.mutex };
    }

    pub fn add(self: *Tensor, other: *const Tensor) !void {
        if (!self.shape.equals(&other.shape)) return Error.ShapeMismatch;
        try self.ensureWritable();
        for (self.data, other.data) |*a, b| {
            a.* += b;
        }
    }

    pub fn sub(self: *Tensor, other: *const Tensor) !void {
        if (!self.shape.equals(&other.shape)) return Error.ShapeMismatch;
        try self.ensureWritable();
        for (self.data, other.data) |*a, b| {
            a.* -= b;
        }
    }

    pub fn mul(self: *Tensor, other: *const Tensor) !void {
        if (!self.shape.equals(&other.shape)) return Error.ShapeMismatch;
        try self.ensureWritable();
        for (self.data, other.data) |*a, b| {
            a.* *= b;
        }
    }

    pub fn div(self: *Tensor, other: *const Tensor) !void {
        if (!self.shape.equals(&other.shape)) return Error.ShapeMismatch;
        try self.ensureWritable();
        for (self.data, other.data) |*a, b| {
            if (b == 0) return Error.DivisionByZero;
            a.* /= b;
        }
    }

    pub fn addScalar(self: *Tensor, scalar: f32) !void {
        try self.ensureWritable();
        for (self.data) |*val| {
            val.* += scalar;
        }
    }

    pub fn mulScalar(self: *Tensor, scalar: f32) !void {
        try self.ensureWritable();
        for (self.data) |*val| {
            val.* *= scalar;
        }
    }

    pub fn fill(self: *Tensor, value: f32) !void {
        try self.ensureWritable();
        @memset(self.data, value);
    }

    pub fn sum(self: *const Tensor) f32 {
        var total: f32 = 0;
        for (self.data) |val| {
            total += val;
        }
        return total;
    }

    pub fn mean(self: *const Tensor) !f32 {
        const size = try self.shape.totalSize();
        if (size == 0) return Error.InvalidShape;
        return self.sum() / @as(f32, @floatFromInt(size));
    }

    pub fn max(self: *const Tensor) !f32 {
        const size = try self.shape.totalSize();
        if (size == 0) return Error.InvalidShape;
        var max_val = self.data[0];
        for (self.data[1..]) |val| {
            if (val > max_val) max_val = val;
        }
        return max_val;
    }

    pub fn min(self: *const Tensor) !f32 {
        const size = try self.shape.totalSize();
        if (size == 0) return Error.InvalidShape;
        var min_val = self.data[0];
        for (self.data[1..]) |val| {
            if (val < min_val) min_val = val;
        }
        return min_val;
    }

    pub fn transpose(self: *Tensor) !void {
        if (self.shape.dims.len != 2) return Error.InvalidShape;
        try self.ensureWritable();
        const rows = self.shape.dims[0];
        const cols = self.shape.dims[1];
        const tmp = try self.allocator.alloc(f32, self.data.len);
        defer self.allocator.free(tmp);
        @memcpy(tmp, self.data);
        for (0..rows) |i| {
            for (0..cols) |j| {
                self.data[j * rows + i] = tmp[i * cols + j];
            }
        }
        const temp_dim = self.shape.dims[0];
        self.shape.dims[0] = self.shape.dims[1];
        self.shape.dims[1] = temp_dim;
        const temp_stride = self.shape.strides[0];
        self.shape.strides[0] = self.shape.strides[1];
        self.shape.strides[1] = temp_stride;
    }

    pub fn matmul(self: *const Tensor, other: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.dims.len != 2 or other.shape.dims.len != 2) return Error.InvalidShape;
        if (self.shape.dims[1] != other.shape.dims[0]) return Error.ShapeMismatch;
        const m = self.shape.dims[0];
        const n = other.shape.dims[1];
        const k = self.shape.dims[1];
        const result = try init(allocator, &[_]usize{ m, n });
        for (0..m) |i| {
            for (0..n) |j| {
                var sum: f32 = 0;
                for (0..k) |l| {
                    sum += self.data[i * k + l] * other.data[l * n + j];
                }
                result.data[i * n + j] = sum;
            }
        }
        return result;
    }

    pub fn slice(self: *Tensor, start: []const usize, end: []const usize) !Tensor {
        if (start.len != self.shape.dims.len or end.len != self.shape.dims.len) return Error.InvalidShape;
        for (start, end, self.shape.dims) |s, e, dim| {
            if (s >= e or e > dim) return Error.InvalidShape;
        }
        var new_dims = try self.allocator.alloc(usize, self.shape.dims.len);
        defer self.allocator.free(new_dims);
        for (start, end, 0..) |s, e, i| {
            new_dims[i] = e - s;
        }
        const new_shape = try Shape.init(self.allocator, new_dims);
        const new_size = try new_shape.totalSize();
        const new_data = try self.allocator.alloc(f32, new_size);
        var idx: usize = 0;
        var indices = try self.allocator.alloc(usize, self.shape.dims.len);
        defer self.allocator.free(indices);
        @memset(indices, 0);
        while (idx < new_size) : (idx += 1) {
            var flat_idx: usize = 0;
            for (indices, start, self.shape.strides) |local_i, s, stride| {
                flat_idx += (local_i + s) * stride;
            }
            new_data[idx] = self.data[flat_idx];
            var carry: usize = self.shape.dims.len;
            while (carry > 0) {
                carry -= 1;
                indices[carry] += 1;
                if (indices[carry] < new_dims[carry]) break;
                indices[carry] = 0;
            }
        }
        const refcount = try self.allocator.create(usize);
        refcount.* = 1;
        const cow = try self.allocator.create(bool);
        cow.* = false;
        const mutex = try self.allocator.create(std.Thread.Mutex);
        mutex.* = .{};
        return .{ .data = new_data, .shape = new_shape, .allocator = self.allocator, .refcount = refcount, .cow = cow, .mutex = mutex };
    }

    pub fn broadcast(self: *const Tensor, target_shape: []const usize, allocator: Allocator) !Tensor {
        if (!self.shape.broadcastCompatible(&Shape{ .dims = @constCast(target_shape), .strides = undefined })) {
            return Error.ShapeMismatch;
        }
        const new_shape = try Shape.init(allocator, target_shape);
        const new_size = try new_shape.totalSize();
        const new_data = try allocator.alloc(f32, new_size);
        const offset = target_shape.len - self.shape.dims.len;
        for (0..new_size) |i| {
            var source_idx: usize = 0;
            var remaining = i;
            for (0..target_shape.len) |j| {
                const dim_idx = target_shape.len - 1 - j;
                const target_dim = target_shape[dim_idx];
                const local_idx = remaining % target_dim;
                remaining /= target_dim;
                if (dim_idx >= offset) {
                    const self_dim_idx = dim_idx - offset;
                    const self_dim = self.shape.dims[self_dim_idx];
                    const mapped_idx = if (self_dim == 1) 0 else local_idx;
                    source_idx += mapped_idx * self.shape.strides[self_dim_idx];
                }
            }
            new_data[i] = self.data[source_idx];
        }
        const refcount = try allocator.create(usize);
        refcount.* = 1;
        const cow = try allocator.create(bool);
        cow.* = false;
        const mutex = try allocator.create(std.Thread.Mutex);
        mutex.* = .{};
        return .{ .data = new_data, .shape = new_shape, .allocator = allocator, .refcount = refcount, .cow = cow, .mutex = mutex };
    }
};
