domain NonnegArith {
  axiom mul_nonneg {
    forall a: Int, b: Int :: a >= 0 && b >= 0 ==> a * b >= 0
  }
  axiom add_nonneg {
    forall a: Int, b: Int :: a >= 0 && b >= 0 ==> a + b >= 0
  }
